import React, { useState } from 'react';
import { Send, CheckCircle2, AlertCircle, Loader2, ClipboardList, User, Calendar, FileText, Hash } from 'lucide-react';

// --- CONFIGURACIÓN ---
// IMPORTANTE: Reemplaza esta URL con la de tu implementación de Web App
const SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbx.../exec'; 

export default function App() {
  const [formData, setFormData] = useState({
    operario: '',
    fecha: new Date().toISOString().split('T')[0],
    tipo: 'Mantenimiento',
    valor: '',
    observaciones: ''
  });

  const [status, setStatus] = useState<'idle' | 'submitting' | 'success' | 'error'>('idle');
  const [message, setMessage] = useState('');

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setStatus('submitting');
    setMessage('');

    try {
      // Usamos fetch con 'no-cors' o text/plain para evitar errores de preflight (CORS)
      // Nota: Google Apps Script debe devolver un resultado JSON, pero el navegador 
      // podría no dejarnos leerlo si no están bien configuradas las cabeceras CORS en el servidor.
      // El modo más seguro para enviar datos sin fallar es usar text/plain.

      const response = await fetch(SCRIPT_URL, {
        method: 'POST',
        headers: {
          'Content-Type': 'text/plain;charset=utf-8',
        },
        body: JSON.stringify(formData)
      });

      if (!response.ok) {
        throw new Error('Error de conexión con el servidor');
      }

      setStatus('success');
      setMessage('Datos registrados correctamente en el sistema.');

      // Resetear formulario tras éxito
      setFormData(prev => ({
        ...prev,
        valor: '',
        observaciones: ''
      }));

      // Volver a estado inicial tras unos segundos
      setTimeout(() => setStatus('idle'), 3000);

    } catch (error) {
      console.error(error);
      setStatus('error');
      setMessage('No se pudo conectar con el servidor. Inténtalo de nuevo.');
    }
  };

  return (
    <div className="min-h-screen bg-slate-100 py-8 px-4 sm:px-6 lg:px-8 flex items-center justify-center">
      <div className="max-w-md w-full space-y-8 animate-fade-in">

        {/* Encabezado */}
        <div className="text-center">
          <div className="mx-auto h-12 w-12 bg-blue-600 rounded-xl flex items-center justify-center shadow-lg transform rotate-3">
            <ClipboardList className="h-7 w-7 text-white" />
          </div>
          <h2 className="mt-6 text-3xl font-extrabold text-slate-900 tracking-tight">
            Registros Aqualia
          </h2>
          <p className="mt-2 text-sm text-slate-600">
            Introduce los parámetros para sincronizar con el sistema.
          </p>
        </div>

        {/* Tarjeta del Formulario */}
        <div className="bg-white py-8 px-4 shadow-xl rounded-2xl sm:px-10 border border-slate-200/60">
          <form className="space-y-6" onSubmit={handleSubmit}>

            {/* Campo: Operario */}
            <div>
              <label htmlFor="operario" className="block text-sm font-medium text-slate-700 mb-1">
                Operario / ID
              </label>
              <div className="relative rounded-md shadow-sm">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <User className="h-5 w-5 text-slate-400" />
                </div>
                <input
                  type="text"
                  name="operario"
                  id="operario"
                  required
                  className="focus:ring-blue-500 focus:border-blue-500 block w-full pl-10 sm:text-sm border-slate-300 rounded-lg p-2.5 bg-slate-50 transition-colors"
                  placeholder="Nombre o Código"
                  value={formData.operario}
                  onChange={handleChange}
                />
              </div>
            </div>

            {/* Campo: Fecha */}
            <div>
              <label htmlFor="fecha" className="block text-sm font-medium text-slate-700 mb-1">
                Fecha de Registro
              </label>
              <div className="relative rounded-md shadow-sm">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Calendar className="h-5 w-5 text-slate-400" />
                </div>
                <input
                  type="date"
                  name="fecha"
                  id="fecha"
                  required
                  className="focus:ring-blue-500 focus:border-blue-500 block w-full pl-10 sm:text-sm border-slate-300 rounded-lg p-2.5 bg-slate-50 transition-colors"
                  value={formData.fecha}
                  onChange={handleChange}
                />
              </div>
            </div>

            {/* Campo: Tipo */}
            <div>
              <label htmlFor="tipo" className="block text-sm font-medium text-slate-700 mb-1">
                Tipo de Actividad
              </label>
              <div className="relative rounded-md shadow-sm">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <FileText className="h-5 w-5 text-slate-400" />
                </div>
                <select
                  name="tipo"
                  id="tipo"
                  className="focus:ring-blue-500 focus:border-blue-500 block w-full pl-10 sm:text-sm border-slate-300 rounded-lg p-2.5 bg-slate-50 transition-colors appearance-none"
                  value={formData.tipo}
                  onChange={handleChange}
                >
                  <option value="Mantenimiento">Mantenimiento</option>
                  <option value="Incidencia">Incidencia</option>
                  <option value="Revisión">Revisión Rutinaria</option>
                  <option value="Lectura">Lectura de Datos</option>
                  <option value="Otro">Otro</option>
                </select>
              </div>
            </div>

            {/* Campo: Valor/Dato */}
            <div>
              <label htmlFor="valor" className="block text-sm font-medium text-slate-700 mb-1">
                Valor / Horas
              </label>
              <div className="relative rounded-md shadow-sm">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Hash className="h-5 w-5 text-slate-400" />
                </div>
                <input
                  type="text"
                  name="valor"
                  id="valor"
                  className="focus:ring-blue-500 focus:border-blue-500 block w-full pl-10 sm:text-sm border-slate-300 rounded-lg p-2.5 bg-slate-50 transition-colors"
                  placeholder="0.0"
                  value={formData.valor}
                  onChange={handleChange}
                />
              </div>
            </div>

            {/* Campo: Observaciones */}
            <div>
              <label htmlFor="observaciones" className="block text-sm font-medium text-slate-700 mb-1">
                Observaciones
              </label>
              <textarea
                name="observaciones"
                id="observaciones"
                rows={3}
                className="shadow-sm focus:ring-blue-500 focus:border-blue-500 block w-full sm:text-sm border-slate-300 rounded-lg p-2.5 bg-slate-50 transition-colors"
                placeholder="Detalles adicionales..."
                value={formData.observaciones}
                onChange={handleChange}
              />
            </div>

            {/* Botón de envío y Estado */}
            <div>
              <button
                type="submit"
                disabled={status === 'submitting' || status === 'success'}
                className={`w-full flex justify-center items-center py-3 px-4 border border-transparent rounded-lg shadow-sm text-sm font-medium text-white transition-all duration-200 
                  ${status === 'success' 
                    ? 'bg-green-600 hover:bg-green-700' 
                    : status === 'error'
                    ? 'bg-red-600 hover:bg-red-700'
                    : 'bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500'
                  } disabled:opacity-75 disabled:cursor-not-allowed`}
              >
                {status === 'submitting' ? (
                  <>
                    <Loader2 className="animate-spin -ml-1 mr-2 h-5 w-5" />
                    Enviando...
                  </>
                ) : status === 'success' ? (
                  <>
                    <CheckCircle2 className="-ml-1 mr-2 h-5 w-5" />
                    Enviado
                  </>
                ) : status === 'error' ? (
                  <>
                    <AlertCircle className="-ml-1 mr-2 h-5 w-5" />
                    Reintentar
                  </>
                ) : (
                  <>
                    <Send className="-ml-1 mr-2 h-5 w-5" />
                    Enviar Registro
                  </>
                )}
              </button>
            </div>

            {/* Mensaje de feedback */}
            {message && (
              <div className={`mt-4 text-center text-sm p-2 rounded-md ${status === 'success' ? 'text-green-700 bg-green-50' : 'text-red-700 bg-red-50'}`}>
                {message}
              </div>
            )}

            {/* Configuración de URL (Opcional: Si no está configurada) */}
            {SCRIPT_URL.includes('INSERT_YOUR') && (
              <div className="mt-4 p-3 bg-yellow-50 text-yellow-800 text-xs rounded border border-yellow-200">
                <strong>Configuración requerida:</strong> Debes editar el archivo <code>App.tsx</code> y colocar la URL de tu Web App en la constante <code>SCRIPT_URL</code>.
              </div>
            )}
          </form>
        </div>

        <div className="text-center text-xs text-slate-400">
          Versión v2.0 &copy; {new Date().getFullYear()} Sistema Interno
        </div>

      </div>
    </div>
  );
}

