                        )}

                        <div className={workflow === 'personal_horas' ? "grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6" : "grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6"}>
                            {currentFields.map(field => {
                                if (field.type === 'textarea') {
